/// Picks the flavor name for this build.
///
/// 1. `--dart-define=FLAVOR=<name>` wins (what the IDE run configurations
///    generated by flutter_flavorizr pass).
/// 2. Otherwise the flavor Flutter itself records for `--flavor <name>`
///    (`appFlavor`), so `flutter build apk --flavor production` is a production
///    build without remembering a second flag.
/// 3. Otherwise `staging`, the safe default for a plain `flutter run`.
String resolveFlavorName({required String explicit, required String? platformFlavor}) {
  if (explicit.isNotEmpty) return explicit;
  if (platformFlavor != null && platformFlavor.isNotEmpty) return platformFlavor;
  return 'staging';
}
